import type { Locale } from "./i18n";
import { baseLanguage } from "./i18n";

/**
 * Base languages product copy may be authored in — mirrors the `language`
 * field of the locale registry in `i18n.ts`. English and French are required;
 * every other language is optional and falls back to English when absent.
 */
export type ContentLanguage =
  | "en"
  | "fr"
  | "ak"
  | "tw"
  | "fat"
  | "ee"
  | "gaa"
  | "ig"
  | "yo"
  | "ha"
  | "de"
  | "pt"
  | "sw"
  | "ar"
  | "ja"
  | "zh";

export type Localized = { en: string; fr: string } &
  Partial<Record<ContentLanguage, string>>;
export type Category = "cocoa" | "oilseeds" | "growing-media";

export interface ProductSpec {
  label: Localized;
  value: Localized;
}

export interface ProductFaq {
  q: Localized;
  a: Localized;
}

export interface Product {
  slug: string;
  category: Category;
  image: string;
  imageAlt: Localized;
  /** Verified photo credit (proper name/license, not translated). */
  credit: string;
  creditUrl: string;
  license: string;
  name: Localized;
  tagline: Localized;
  overview: Localized[];
  history: Localized[];
  uses: { title: Localized; text: Localized }[];
  specs: ProductSpec[];
  quality: Localized[];
  packaging: Localized[];
  buyers: { title: Localized; text: Localized }[];
  faqs: ProductFaq[];
  featured?: boolean;
}

export const t = (l: Localized, locale: Locale): string =>
  l[baseLanguage(locale) as ContentLanguage] ?? l.en;

const file = (name: string, width = 1280) =>
  `https://commons.wikimedia.org/wiki/Special:FilePath/${name}?width=${width}`;

