        gaa: "Ato nu mli yɛmɔ he dawuro dani awo mli; agbeɔ lot ni esaaa, akɛkaa wo o. Atoɔ bɔsai lɛ yɛ shikpɔŋ nɔ yɛ te shishi, ni atɔɔ fɔ yɛ kontenna mli ni atsuɔ nu ni yɔɔ fɔ mli le he ni gbɛ lɛ biɔ.",
        ig: "A na-enyocha mmiri tupu etinye n'akpa; a na-ajụ lot ndị na-adabaghị, a naghị agwakọta ha. A na-echekwa akpa ndị ahụ n'elu ala n'okpuru ndo, a na-ekwe ka ikuku banye n'ụgbọ mmiri ma wepụ mmiri ebe ụzọ chọrọ.",
        yo: "A ń dán ọ̀rinrin wò kí a tó kó sínú àpò; a ń kọ̀ àwọn lot tí kò yẹ, a kì í dà wọ́n pọ̀. A ń tọ́jú àpò náà sókè ilẹ̀ lábẹ́ ibòji, a sì ń jẹ́ kí atẹ́gùn wọ inú kọ̀ntéìnà, a ń mú ọ̀rinrin kúrò níbi tí ọ̀nà bá béèrè.",
        ha: "Ana gwada danshi kafin a sa cikin buhu; ana watsi da lot da ba su dace ba, ba a haɗa su. Ana ajiye buhunan a saman ƙasa a ƙarƙashin rufi, kuma ana ba da iska ga kwantena da cire danshi inda hanya ta buƙata.",
        de: "Feuchtigkeit wird vor dem Abfüllen geprüft; Partien außerhalb der Norm werden zurückgewiesen, nicht vermischt. Die Säcke werden erhöht und überdacht gelagert, und Container werden belüftet und entfeuchtet, wo die Route es erfordert.",
