        ar: "تُختبر الرطوبة قبل التعبئة؛ وتُرفض الدفعات غير المطابقة ولا تُخلط. وتُخزَّن الأكياس مرفوعة عن الأرض وتحت غطاء، وتُهوّى الحاويات ويُزال الرطوبة منها حيثما تطلّب المسار ذلك.",
