        ha: "Man shanu yana da ƙarfi a yanayin zafi na yau da kullum amma yana narkewa cikin zafi: jigilar shi kuma a ajiye shi a sanyi, nesa da wari mai ƙarfi. Ana ba da shawara deodorised grade don sarkar samar da kayan kwalliya a yanayin zafi.",
        de: "Butter ist bei Umgebungstemperatur fest, schmilzt aber in Hitze: kühl versenden und lagern, fern von starken Gerüchen. Für Kosmetik-Lieferketten in warmem Klima wird die desodorierte Qualität empfohlen.",
        pt: "A manteiga é sólida à temperatura ambiente mas derrete com o calor: enviar e armazenar em local fresco, longe de odores fortes. O grau desodorizado é recomendado para cadeias de abastecimento cosmético em climas quentes.",
        sw: "Siagi ni ngumu katika halijoto ya kawaida lakini huyeyuka kwa joto: safirisha na uhifadhi mahali pa baridi, mbali na harufu kali. Daraja lililoondolewa harufu linapendekezwa kwa minyororo ya ugavi wa vipodozi katika hali ya hewa ya joto.",
        ar: "الزبدة صلبة في درجة الحرارة المحيطة لكنها تنصهر في الحرارة: اشحنها وخزّنها في مكان بارد بعيداً عن الروائح القوية. يُوصى بالدرجة منزوعة الرائحة لسلاسل توريد مستحضرات التجميل في المناخات الحارة.",
        ja: "バターは常温では固体ですが、熱で溶けます。涼しく、強い臭いを避けて輸送・保管してください。温暖な気候の化粧品サプライチェーンには脱臭グレードをお勧めします。",
        zh: "可可脂在常温下为固体，但遇热会融化：请冷藏运输和储存，远离强烈气味。温暖气候下的化妆品供应链建议使用脱臭等级。",
