        ja: "カカオマスからバターの一部を圧搾した後、残った固形分がプレスケーキになります。飲料や製パン向けの粉末に挽くか、飼料配合に直接使用します。",
        zh: "从可可液块中压榨出部分可可脂后，剩余的固体形成压饼——研磨成粉用于饮品和烘焙，或直接用于饲料配制。",
