        de: "Lange vor industrieller Lauge war Schalenasche die Alkali-Quelle westafrikanischer Seife und Küche — die leeren Schalen jeder Ernte wurden zur Seife und zum Dünger der nächsten Saison. Industrie- und Bio-Käufer beziehen sie heute als natürlichen, rückverfolgbaren alkalischen Rohstoff.",
        pt: "Muito antes da soda industrial, a cinza de cascas era o álcali do sabão e da cozinha da África Ocidental — as cascas vazias de cada colheita tornavam-se o sabão e o fertilizante da estação seguinte. Compradores industriais e orgânicos abastecem-se hoje dela como insumo alcalino natural e rastreável.",
